import "./oderlist.css";
import { useCart } from "./CartContext";
imp
const OrderList = () => {
    const { orders } = useCart(); // Use the context to get orders

    if (!orders || orders.length === 0) {
        return <p>Chưa có đơn hàng nào.</p>;
    }

    return (
        <div className="order-list">
            <h2>📦 Đơn hàng đã đặt</h2>
            {orders.map((order) => (
                <div key={order.id} className="order-item">
                    <h3>🆔 Đơn hàng #{order.id}</h3>
                    <p>📅 Ngày đặt: {order.date}</p>
                    <p>💵 Tổng tiền: {order.total}k</p>




                </div>
            ))}
            <div>
                {cart.map((product) => (
                    <div key={product.id} className="cart-item">
                        <img src={product.image} alt={product.name} className="product-image" />
                        <span>{product.name} - {product.price}k</span>
                        <button className="btnCart" onClick={() => removeFromCart(product.id)}>Xóa</button>
                    </div>
                ))}
            </div>
        </div>
    );
};

export default OrderList;
